PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY, name TEXT NOT NULL, color TEXT NOT NULL DEFAULT '#6c8cff', icon TEXT NOT NULL DEFAULT '📁');
CREATE TABLE IF NOT EXISTS boards(id INTEGER PRIMARY KEY, workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, bg TEXT NOT NULL DEFAULT '#1f2937', fav INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS lists(id INTEGER PRIMARY KEY, board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE, name TEXT NOT NULL, pos REAL NOT NULL, color TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS cards(id INTEGER PRIMARY KEY, list_id INTEGER NOT NULL REFERENCES lists(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', due TEXT, priority INTEGER NOT NULL DEFAULT 0, pos REAL NOT NULL, archived INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, done INTEGER NOT NULL DEFAULT 0, recur TEXT NOT NULL DEFAULT '', fields TEXT NOT NULL DEFAULT '', start TEXT, est INTEGER NOT NULL DEFAULT 0, spent INTEGER NOT NULL DEFAULT 0, timer INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS labels(id INTEGER PRIMARY KEY, board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE, name TEXT NOT NULL, color TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS card_labels(card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE, label_id INTEGER NOT NULL REFERENCES labels(id) ON DELETE CASCADE, PRIMARY KEY(card_id,label_id));
CREATE TABLE IF NOT EXISTS checklist_items(id INTEGER PRIMARY KEY, card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE, text TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0, pos REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS attachments(id INTEGER PRIMARY KEY, card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE, name TEXT NOT NULL, path TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS card_deps(card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE, depends_on INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE, PRIMARY KEY(card_id,depends_on));
CREATE TABLE IF NOT EXISTS activity(id INTEGER PRIMARY KEY, card_id INTEGER, text TEXT NOT NULL, at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS inbox(id INTEGER PRIMARY KEY, text TEXT NOT NULL, at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS templates(id INTEGER PRIMARY KEY, name TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS milestones(id INTEGER PRIMARY KEY, board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE, name TEXT NOT NULL, due TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS filters(id INTEGER PRIMARY KEY, name TEXT NOT NULL, data TEXT NOT NULL);
